    @Transactional
    public SettingValue setRounding(String sheetId, String by, String mode, LocalDate from) {
        if (mode != null && !ROUNDING_MODES.containsKey(mode)) {
            throw new IllegalArgumentException("No rounding mode " + mode);
        }
        sheets.lock(sheetId);
